(()=>{'use strict';let checking=false;
const previousAdmin=adminHTML;adminHTML=function(){if(view!=='health')return previousAdmin();return head('تشغيل موثوق','صحة الخدمة والنسخ الاحتياطية','مؤشرات تشغيل مبسطة وسجل استرجاع البطاقات.')+'<section class="panel"><div id="operations-status" aria-live="polite">جارٍ قراءة الحالة…</div><div class="actions mt"><button class="btn secondary" data-operation-health="refresh">تحديث الحالة</button><button class="btn primary" data-operation-health="backup">إنشاء نسخة احتياطية الآن</button></div><p class="sub mt">نسخة تلقائية يوميًا، مع الاحتفاظ بآخر سبع نسخ ضمن حد التخزين. النسخ محلية على قرص الخدمة؛ يلزم حفظ نسخة مستقلة خارجه للتعافي من فقد القرص.</p><p class="sub">اختبارات الكاميرا والبريد الفعلية يتأكد منها فريق التشغيل قبل الإطلاق.</p></section><section class="panel mt"><h2>سجل استرجاع البطاقات</h2><div id="recovery-audit-list"></div></section>';};
async function status(){if(checking||role!=='admin'||view!=='health')return;checking=true;try{const data=await api('/api/operations/status'),box=document.querySelector('#operations-status');if(!box)return;box.innerHTML=`<div class="grid2"><p>زمن الاستجابة · 95٪ من الطلبات: <strong>${fmt(data.p95Ms)} مللي ثانية</strong></p><p>ذاكرة الخدمة: <strong>${fmt(data.memoryMB)} MB</strong></p><p>أخطاء الخادم منذ التشغيل: <strong>${fmt(data.errorCount)}</strong></p><p>نسخ محفوظة: <strong>${fmt(data.backup.count)}</strong></p></div><p>${data.backup.failure?'⚠ تعذر إنشاء آخر نسخة. راجع سجل الخدمة.':data.backup.last?'آخر نسخة: '+esc(new Date(data.backup.last.created).toLocaleString('ar-SA')):'لم تُنشأ نسخة خلال جلسة التشغيل الحالية بعد.'}</p><p>تشفير النسخ: ${data.backup.encrypted?'مفعّل':'غير مفعّل؛ احفظ النسخ في مكان خاص.'}</p>`;const audit=await api('/api/operations/recovery');const target=document.querySelector('#recovery-audit-list');if(target)target.innerHTML='<div class="table-scroll"><table><thead><tr><th>الوقت</th><th>البطاقة</th><th>الإجراء</th><th>المنفذ</th></tr></thead><tbody>'+audit.rows.map(r=>`<tr><td>${esc(new Date(r.time).toLocaleString('ar-SA'))}</td><td>${esc(r.shop)}</td><td>${r.event==='issued'?'إصدار رابط':'استعمال الرابط'}</td><td>${esc(r.issuer_kind)} · ${esc(r.issuer_id)}</td></tr>`).join('')+'</tbody></table></div>';}catch(e){const box=document.querySelector('#operations-status');if(box)box.textContent=e.message;}finally{checking=false;}}
const before=render;render=function(){before();if(serverMode&&role==='admin'&&!db.scopedBusiness){const nav=document.querySelector('.sidebar nav,nav[aria-label="القائمة الرئيسية"]');if(nav&&!nav.querySelector('[data-operation-health]'))nav.insertAdjacentHTML('beforeend','<button class="nav-item" data-operation-health="open">صحة الخدمة</button>');if(view==='health')status();}};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-operation-health]');if(!b)return;if(b.dataset.operationHealth==='open'){view='health';render();return;}if(b.dataset.operationHealth==='backup'){b.disabled=true;try{await api('/api/operations/backup',{});toast('تم إنشاء النسخة والتحقق من سلامتها.');}catch(error){toast(error.message);}finally{b.disabled=false;}}status();});
})();
